CREATE OR REPLACE FUNCTION pct_to_numeric(pct_str text)
RETURNS numeric AS $$
BEGIN
    -- Remove the '%' sign and convert to numeric
    RETURN NULLIF(TRIM(pct_str), '')::numeric / 100;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE OR REPLACE FUNCTION pct_to_numeric(pct_str text)
RETURNS numeric AS $$
BEGIN
    RETURN (REPLACE(TRIM(pct_str), '%', '')::numeric) / 100;
END;
$$ LANGUAGE plpgsql IMMUTABLE;
